oxy_webhelp_navlinks = {"ibm_db2-d39307e34020":{"topics":[{"title":"Introduction to Db2 protection","href":"db2\/ibm_db2_protection_overview.html","menu":{"hasChildren":false},"tocID":"tocId-d39307e34036","next":"tocId-d39307e34036"},{"title":"High-level implementation workflow for Db2","shortdesc":"<p class=\"shortdesc\">The Db2 protection implementation workflow involves a structured approach to secure         data management, starting with planning and preparation, followed by Db2 workload setup,         protection configuration, ongoing management, high availability configuration where         required, and workload recovery.<\/p>","href":"db2\/high_level_impl_workflow_db2.html","attributes":{"data-id":"high_level_impl_workflow_db2"},"menu":{"hasChildren":false},"tocID":"high_level_impl_workflow_db2-d39307e34093","topics":[]},{"title":"Quick links for Db2","shortdesc":"<p class=\"shortdesc\">Immediate access to the most-used Db2 setup, day-to-day operations, and recovery         tasks.<\/p>","href":"db2\/quick_links_db2.html","attributes":{"data-id":"quick_links_db2"},"menu":{"hasChildren":false},"tocID":"quick_links_db2-d39307e34104","topics":[]},{"title":"Plan Db2 protection","shortdesc":"<p class=\"shortdesc\">Before adding Db2 hosts and instances to <span class=\"ph\">RSC<\/span>, you can plan your         deployment by reviewing the workload requirements, configuration parameters, role-based         access control permissions, and known limitations.<\/p>","href":"db2\/plan_db2_protection.html","attributes":{"data-id":"plan_db2_protection"},"menu":{"hasChildren":false},"tocID":"plan_db2_protection-d39307e34115","next":"plan_db2_protection-d39307e34115"},{"title":"Set up Db2 workload","shortdesc":"<p class=\"shortdesc\">You can set up your Db2 workload by adding Db2 hosts and database instances to <span class=\"ph\">RSC<\/span>, and by configuring Db2 pureScale clusters where         applicable.<\/p>","href":"db2\/setup_db2_workload.html","attributes":{"data-id":"setup_db2_workload"},"menu":{"hasChildren":false},"tocID":"setup_db2_workload-d39307e34185","next":"setup_db2_workload-d39307e34185"},{"title":"Set up Db2 protection","shortdesc":"<p class=\"shortdesc\">Setting up protection for Db2 instances and databases involves evaluating SLA Domain         options, assigning protection, and configuring archival, on-demand snapshots, retention,         legal holds, parallelism, and sessions.<\/p>","href":"db2\/setup_protection_db2.html","attributes":{"data-id":"setup_protection_db2"},"menu":{"hasChildren":false},"tocID":"setup_protection_db2-d39307e34293","next":"setup_protection_db2-d39307e34293"},{"title":"Manage Db2 objects","shortdesc":"<p class=\"shortdesc\">Managing Db2 instances and databases in <span class=\"ph\">RSC<\/span> includes viewing, editing,         refreshing, and deleting Db2 database instances, accessing database details and snapshots,         and viewing events.<\/p>","href":"db2\/manage_db2_objects.html","attributes":{"data-id":"manage_db2_objects"},"menu":{"hasChildren":false},"tocID":"manage_db2_objects-d39307e34532","next":"manage_db2_objects-d39307e34532"},{"title":"Configure high availability for Db2","shortdesc":"<p class=\"shortdesc\">Db2 high availability with <span class=\"ph\">RSC<\/span> supports Db2 high availability clustering and High Availability Disaster Recovery (HADR).<\/p>","href":"db2\/configure_high_availability_db2.html","attributes":{"data-id":"configure_high_availability_db2"},"menu":{"hasChildren":false},"tocID":"configure_high_availability_db2-d39307e34659","next":"configure_high_availability_db2-d39307e34659"},{"title":"Recover Db2","shortdesc":"<p class=\"shortdesc\">When incidents that result in data failure or corruption occur, the Db2 restore and         rollforward processes recover data from backups to ensure that all data is available,         accurate, and complete.<\/p>","href":"db2\/recover_db2.html","attributes":{"data-id":"recover_db2"},"menu":{"hasChildren":false},"tocID":"recover_db2-d39307e34761","next":"recover_db2-d39307e34761"},{"title":"Access Db2 reports","shortdesc":"<p class=\"shortdesc\">You can use reports in <span class=\"ph\">RSC<\/span> to track the protection status, SLA compliance,         and backup activity of Db2 instances and databases for audits, compliance reviews, and data         management planning.<\/p>","href":"db2\/access_db2_reports.html","attributes":{"data-id":"access_db2_reports"},"menu":{"hasChildren":false},"tocID":"access_db2_reports-d39307e35125","next":"access_db2_reports-d39307e35125"},{"title":"Troubleshooting Db2","shortdesc":"<p class=\"shortdesc\">You can diagnose and resolve common issues that affect Db2 host discovery, log archival,         backups, and rollforward operations in <span class=\"ph\">RSC<\/span>.<\/p>","href":"db2\/troubleshooting_db2.html","attributes":{"data-id":"troubleshooting_db2"},"menu":{"hasChildren":false},"tocID":"troubleshooting_db2-d39307e35154","topics":[]}]}};